def piolaAffineHomotopy {n : ℕ} (f₀ f₁ : PiolaSpace n → PiolaSpace n)
    (z : PiolaSpace (n + 1)) : PiolaSpace n :=
  (1 - z (Fin.last n)) • f₀ (Fin.init z) + z (Fin.last n) • f₁ (Fin.init z)

